-- Ticket types from the Dante interview (WA-208): specific Quality of Life Complaint types, a License
-- category and NYPD Community Engagement. Liquor License is renamed License - Liquor License.
--
-- Sets the list on EVERY board, replacing each board's current ticket_types, so a board that customized
-- its types loses that. Tickets keep their type text, so only Liquor License rows (and any pending
-- suggestion that proposes it) are updated. css_class reuses the existing colors: quality, safety, and
-- liquor for all three License types. Run by hand in the SQL editor or with the Supabase CLI.

update public.boards
set ticket_types = '[{"label": "Quality of Life Complaint", "css_class": "quality", "definition": "Ongoing neighborhood conditions that affect daily life, such as sidewalk obstruction, garbage, restroom locations or sanitation. Use a more specific Quality of Life Complaint type when one fits."}, {"label": "Quality of Life Complaint - Broken Streetlights", "css_class": "quality", "definition": "Streetlights that are out, flickering, damaged or missing, including requests for new lighting on a block."}, {"label": "Quality of Life Complaint - Potholes", "css_class": "quality", "definition": "Potholes, cave-ins and damaged road surface. Use Transportation Request instead for street redesign or repaving plans."}, {"label": "Quality of Life Complaint - Ponding or Flooding", "css_class": "quality", "definition": "Standing water, street flooding and poor drainage after rain. Use Clogged Catch Basins when a blocked drain is named as the cause."}, {"label": "Quality of Life Complaint - Clogged Catch Basins", "css_class": "quality", "definition": "Storm drains and catch basins that are blocked, clogged or need cleaning."}, {"label": "Quality of Life Complaint - Illegal Parking", "css_class": "quality", "definition": "Illegal, double, blocked-hydrant, bike-lane or abandoned-vehicle parking, and requests for parking enforcement."}, {"label": "Quality of Life Complaint - Noise from Commercial Establishments", "css_class": "quality", "definition": "Noise from bars, restaurants, clubs, construction and other businesses. Use License - Liquor License for a liquor license hearing about the same business."}, {"label": "Quality of Life Complaint - Noise from Residents", "css_class": "quality", "definition": "Noise from homes, apartments and neighbors, including parties and music."}, {"label": "Quality of Life Complaint - Tree Pruning", "css_class": "quality", "definition": "Requests to prune, remove, plant or inspect street trees."}, {"label": "Quality of Life Complaint - Gas or Hot-Water Shutoffs", "css_class": "quality", "definition": "Gas, heat or hot-water shutoffs in homes and buildings, including emergency shutoffs."}, {"label": "Public Safety Issue", "css_class": "safety", "definition": "Crime, drug activity, policing, or hazards to personal safety, such as dark areas in a park. Use this when the underlying problem is safety, even if the response is enforcement."}, {"label": "Public Safety Issue - NYPD Community Engagement", "css_class": "safety", "definition": "Requests for NYPD presence at community events and meetings, precinct updates, and community council or officer outreach."}, {"label": "License - Liquor License", "css_class": "liquor", "definition": "Anything involving the State Liquor Authority, including new applications, renewals, stipulations, resolution corrections, and SLA hearings."}, {"label": "License - Cannabis License", "css_class": "liquor", "definition": "Cannabis dispensary license applications, notices and hearings with the Office of Cannabis Management."}, {"label": "License - Sidewalk Café License", "css_class": "liquor", "definition": "Sidewalk café license applications, renewals and hearings with the city."}, {"label": "Land Use Request", "css_class": "land-use", "definition": "Development proposals, zoning, housing plans, RFPs, and requests to use or build on a site, including city-owned property, piers, and markets."}, {"label": "Transportation Request", "css_class": "transport", "definition": "Transit service, street design, traffic safety, congestion, and requests to or from DOT or MTA. Use Quality of Life Complaint instead when the issue is a street nuisance rather than how the street or transit works."}, {"label": "Other", "css_class": "other", "definition": "An action item that fits no other type, such as schools or social services. If several tickets in Other share a topic, consider making it a new type."}, {"label": "Budget Priority", "css_class": "budget", "definition": "The board''s district needs statement and its ranked expense and capital budget priorities for city agencies."}, {"label": "Board Administration", "css_class": "admin", "definition": "The board''s internal operations, including membership, mentors, trainings, elections, bylaws, attendance, and scheduling."}]'::jsonb;

update public.tickets
set type = 'License - Liquor License'
where type = 'Liquor License';

update public.ticket_suggestions
set changes = jsonb_set(changes, '{type}', '"License - Liquor License"')
where status = 'pending' and changes->>'type' = 'Liquor License';
